using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {typeInfo.Type.Name}");

// Use it to serialize
string json = JsonSerializer.Serialize(new Person("Alice", 42), typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// Case A: type metadata IS available (default resolver handles any type)
if (options.TryGetTypeInfo<Person>(out var personInfo))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded — Type: {personInfo!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> returned false");
}

// Case B: use a custom resolver that only knows about Person,
//         so probing for int[] will return false instead of throwing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Only allow Person through; block everything else.
            if (ti.Type != typeof(Person))
                ti.Kind = JsonTypeInfoKind.None; // mark unsupported
        })
};

// This won't throw — it just returns false.
if (limited.TryGetTypeInfo<int[]>(out var arrayInfo))
{
    Console.WriteLine($"TryGetTypeInfo<int[]> succeeded — unexpected!");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int[]> returned false — metadata not available (no exception thrown)");
}

// Record used for the demo
public record Person(string Name, int Age);

